# 3. Transformare date în tabel Pandas
df_anvelope = pd.read_csv(io.StringIO(date_excel_complet))
df_anvelope.columns = df_anvelope.columns.str.strip()

# 4. Căsuța de Căutare din aplicație
termen_cautat = st.text_input("🔍 Caută după Număr Auto (ex: B119FEK) sau Seria de Șasiu (VIN):").upper().strip()

if termen_cautat:
    # Scanare în coloanele RegistrationNumber și Fleet VIN
    rezultate = df_anvelope[
        df_anvelope['RegistrationNumber'].astype(str).str.upper().str.contains(termen_cautat) | 
        df_anvelope['Fleet VIN'].astype(str).str.upper().str.contains(termen_cautat)
    ]

    if not rezultate.empty:
        st.success(f"✅ Am găsit {len(rezultate)} anvelope în custodie pentru '{termen_cautat}':")
        
        # Extragere detalii generale din prima linie găsită
        prima_linie = rezultate.iloc[0]
        
        col1, col2 = st.columns(2)
        with col1:
            st.info(f"👤 **Companie Client:** {prima_linie.get('FleetName', 'N/A')}")
        with col2:
            st.info(f"🚗 **Model Autovehicul:** {prima_linie.get('Make/Model', 'N/A')}")

        st.write("### 📋 Listă anvelope în depozit:")
        
        # Selectăm coloanele utile pentru a nu aglomera ecranul
        coloane_vizibile = ['RegistrationNumber', 'BRAND', 'ProductGroup', 'MaterialDescription', 'TreadDepth', 'DOT', 'StorageNote(Comments/AccessoriesStored)']
